// Clean autonomy index — record JAH-GPC-ROBOTVACUUM-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"suction_pa": 5000, "runtime_min": 180, "price_usd": 600};
var value = (m.suction_pa*m.runtime_min/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-ROBOTVACUUM-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-ROBOTVACUUM-000001|' + value.toFixed(2) + ' autonomy index');

